import{_ as o,o as a,c as i,a2 as r}from"./chunks/framework.x7b91k6X.js";const m=JSON.parse('{"title":"漫画 · 第 12 话 端上智能：Core ML 与设备侧 AI","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.12-on-device-ai.md","filePath":"comics/EP.12-on-device-ai.md","lastUpdated":1792677465000}'),t={name:"comics/EP.12-on-device-ai.md"};function l(n,e,s,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="漫画-·-第-12-话-端上智能-core-ml-与设备侧-ai" tabindex="-1">漫画 · 第 12 话 端上智能：Core ML 与设备侧 AI <a class="header-anchor" href="#漫画-·-第-12-话-端上智能-core-ml-与设备侧-ai" aria-label="Permalink to &quot;漫画 · 第 12 话 端上智能：Core ML 与设备侧 AI&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../12-on-device-ai">12-on-device-ai.md</a> ｜ 原画：<a href="./EP.12-on-device-ai.svg">EP.12-on-device-ai.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>斯威芙蒂</strong>：图片识别全走云端，延迟 1.2 秒用户流失、隐私数据出境有合规风险、地铁无网功能全瘫。</li><li><strong>Runtime 长老</strong>：教她用 Core ML + Vision 把推理搬到设备侧，配合端云降级链。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>全靠云端 AI 有三连痛：慢（延迟高）、贵（算力成本）、怕断网。端上推理不是替代云端，而是把高频、隐私、离线场景留在设备侧。Core ML 负责运行自定义模型，Vision 提供内置 OCR/图像分类能力。策略是「端上优先、低置信度升级云端、云端失败给默认值」的三级降级链，保证任何情况下都有结果。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>全云端推理的三个问题：</p><ul><li><strong>延迟</strong>：上传图片→云端推理→返回结果，即使网络好也要 500ms+，用户感知明显；</li><li><strong>隐私</strong>：用户照片、文本传到云端，涉及 GDPR/个保法合规，尤其是医疗、金融场景；</li><li><strong>离线</strong>：地铁、电梯、飞机上无网络，AI 功能直接不可用。</li></ul><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>端云协同决策：</p><ul><li><strong>端上推理优先</strong>：Core ML 运行 <code>.mlmodelc</code> 编译后的模型，Vision 框架提供内置能力（<code>VNRecognizeTextRequest</code> OCR、<code>VNClassifyImageRequest</code> 图像分类），无需自带模型即可开箱即用。</li><li><strong>云端兜底</strong>：端上模型精度不够、置信度低、或模型未就绪时，升级到云端大模型复核。</li><li><strong>模型量化</strong>：训练时用 FP32，部署时量化为 FP16 或 INT8，体积缩小 50-75%，推理速度提升，精度损失可控。</li><li><strong>编译优化</strong>：Xcode 编译时把 <code>.mlmodel</code> 转成 <code>.mlmodelc</code>，首次加载更快。</li></ul><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>三级降级链：</p><ol><li><strong>端上高置信度直接返回</strong>：<code>confidence &gt; 0.8</code> 就用端上结果，毫秒级；</li><li><strong>低置信度升级云端</strong>：端上拿不准时调云端大模型复核；</li><li><strong>云端失败给默认值</strong>：网络异常或云端超时，返回默认值或提示重试，绝不白屏。</li></ol><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><ol><li>端云协同：端上低延迟+隐私+离线，云端高精度+大模型，按场景路由。</li><li>模型量化减小体积，Core ML 编译期转 .mlmodelc 提速加载。</li><li>降级链：端上→云端→默认值，保证任何情况下都有结果不白屏。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：端上推理一定比云端快吗？什么时候反而该用云端？</p><p><strong>答</strong>：不一定。端上推理快的前提是「模型已加载到内存、输入数据在本地」。如果模型很大（几 GB），首次加载可能要几秒，反而比云端慢。该用云端的场景：①模型太大无法放端上（如千亿参数大模型）；②需要持续更新的知识（实时数据）；③端上 NPU/GPU 资源紧张（老旧设备）。决策原则是：<strong>能端上就端上（隐私+离线），必须云端才云端（精度+规模）</strong>，两者配合而非二选一。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><p>运行 <code>swift run OnDeviceAI</code>，查看 <code>VisionTextRecognizer.swift</code>（OCR）、<code>ImageClassifier.swift</code>（图像分类）和 <code>InferencePolicy.swift</code>（端云决策）的实现；阅读第 12 章的模型量化方法和降级链设计。</p><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>AI 功能上线了，可海外用户看不懂中文、盲人用户用不了 VoiceOver。第 13 话《国际化与无障碍》，让 App 走遍全球、人人可用。</p>',25)])])}const g=o(t,[["render",l]]);export{m as __pageData,g as default};
